Tool response:
Tool: find_segments
Description: Find Segments
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "description": "Segment name",
          "title": "Name"
        }
      },
      "required": [
        "name"
      ]
    }

Tool response:
Tool: create_campaign
Description: Create Campaign
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "title": "Name"
        },
        "description": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Description"
        },
        "start_date": {
          "type": "string",
          "title": "Start Date"
        },
        "end_date": {
          "type": "string",
          "title": "End Date"
        },
        "points_multiplier": {
          "type": "number",
          "title": "Points Multiplier"
        },
        "target_segment_name": {
          "type": "string",
          "title": "Target Segment Name"
        },
        "auto_apply": {
          "type": "boolean",
          "title": "Auto Apply"
        }
      },
      "required": [
        "name",
        "start_date",
        "end_date",
        "points_multiplier",
        "target_segment_name",
        "auto_apply"
      ]
    }
